import{_ as e,o as r,c as o,a3 as i}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"物流原理与一些名词","description":"","frontmatter":{"translationSource":{"title":"物流原理与一些名词","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/logistics-principles-and-frontier-research"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/logistics-principles-and-frontier-research"}]]},"headers":[],"relativePath":"zh/logistics-principles-and-frontier-research.md","filePath":"zh/page-Ul3PjfHfEH7t9ofd3SfA1L.md"}'),t={name:"zh/logistics-principles-and-frontier-research.md"};function n(s,a,l,p,h,d){return r(),o("div",null,[...a[0]||(a[0]=[i('<div class="logistics-content"><h1 id="物流原理与一些名词" tabindex="-1">物流原理与一些名词 <a class="header-anchor" href="#物流原理与一些名词" aria-label="Permalink to &quot;物流原理与一些名词&quot;">​</a></h1><blockquote><p>源页面 ID：<code>Ul3PjfHfEH7t9ofd3SfA1L</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span class="mark-red"><strong>十分严重的缺乏维护，应当讨论该子页面下目录是否合理</strong></span></p><p><span id="source-block-wO7xPIiHDJwfeAtqFW4VJE"></span></p><h2 id="均匀性与极差" tabindex="-1">均匀性与极差 <a class="header-anchor" href="#均匀性与极差" aria-label="Permalink to &quot;均匀性与极差&quot;">​</a></h2><p><span id="source-block-Ik2ViXezbe9d6VFUOZIUc6"></span></p><h2 id="一些各式各样的特殊结构定义" tabindex="-1">一些各式各样的特殊结构定义 <a class="header-anchor" href="#一些各式各样的特殊结构定义" aria-label="Permalink to &quot;一些各式各样的特殊结构定义&quot;">​</a></h2><p><span id="source-block-f5f4WE5OyQHLDbhWbKgmAv"></span></p><h3 id="滤波器" tabindex="-1">滤波器 <a class="header-anchor" href="#滤波器" aria-label="Permalink to &quot;滤波器&quot;">​</a></h3><p>狭义滤波器：将输入的不均匀序列转化为更加均匀的序列，例如将10110 10011转化为10110 10110，有时也被叫做稳流器</p><p>在满带输入的情况下等同于某种较为均匀的限流器</p><p>广义滤波器：低通：将超过设定流量范围的序列流放到其他地方，通常为插入低于设定流量范围的序列中或者流出结构。高通：与低通相反。</p><p><span id="source-block-9j2XLqzFcpwJ8W5QQIYeRK"></span></p><h3 id="整流器" tabindex="-1">整流器 <a class="header-anchor" href="#整流器" aria-label="Permalink to &quot;整流器&quot;">​</a></h3><p>狭义整流器：将输入的序列转化为连续1/0序列，例如将10110 10011转化为11100 11100</p><p>在满带输入下对上游传递连续1/0序列的阻塞信号</p><p>广义整流器：将输入流转化为特定结构流量，典型的是转化为连续流和0流量，还有转化为特定序列，例如完美均匀序列</p><p><span id="source-block-dey4t7kblTAWoIHHqzUYE7"></span></p><h3 id="溢流器" tabindex="-1">溢流器 <a class="header-anchor" href="#溢流器" aria-label="Permalink to &quot;溢流器&quot;">​</a></h3><p>狭义溢流器：输入在两个输出口之间有严格优先级关系，即在A没有满到无法输出前B都不会有流量。</p><p>广义溢流器：输入在两个输出口之间有不严格优先级关系，即在空载情况下，输出到高优先A方向的流量大于A满载时最大通行流量。</p><p><span id="source-block-n9B7tFb0RiVmFdwgWv9DxN"></span></p><h3 id="限流器" tabindex="-1">限流器 <a class="header-anchor" href="#限流器" aria-label="Permalink to &quot;限流器&quot;">​</a></h3><p>单入口单出口的物流结构，限制平均通过流量的上限，不保证输出为特定序列。有时也叫做限速器。</p><p><span id="source-block-gk0ftJwaqdj335twrpq0qB"></span></p><h3 id="优先汇流器" tabindex="-1">优先汇流器 <a class="header-anchor" href="#优先汇流器" aria-label="Permalink to &quot;优先汇流器&quot;">​</a></h3><p>基于优先汇流 的原理制作的 分流器→汇流器;传送带→汇流器 结构，由于总流量小于等于1，当高优先方向输入流量1时，低优先方向就会变成流量0，使得低优先方向&quot;阻断&quot;。</p><p><span id="source-block-Tr4QvYq1Ruz7WvejwO5RcS"></span></p><h3 id="筛分器-过滤器-分类器-分离器" tabindex="-1">筛分器\\过滤器\\分类器\\分离器 <a class="header-anchor" href="#筛分器-过滤器-分类器-分离器" aria-label="Permalink to &quot;筛分器\\过滤器\\分类器\\分离器&quot;">​</a></h3><p>本段内若有引用均使用分类器的称呼，本质是分流器→只能接受某种流体\\物品的容器，通常容器使用的是过滤准入口。有时有特殊需求（压元件、压地）会使用类似管道\\暗管只能存储一种流体、固气\\液气机激活物口只接受激活物之类的设备代替容器。</p><p><span id="source-block-43mxU8WxSkD6eR8LkKUVn8"></span></p><h3 id="取反器-回流器" tabindex="-1">取反器\\回流器 <a class="header-anchor" href="#取反器-回流器" aria-label="Permalink to &quot;取反器\\回流器&quot;">​</a></h3><p><span id="source-block-TwAdfmWti8bBHTAGCmTcqt"></span></p><h3 id="基本控制结构" tabindex="-1">基本控制结构 <a class="header-anchor" href="#基本控制结构" aria-label="Permalink to &quot;基本控制结构&quot;">​</a></h3><p>基本控制结构是两输入两输出的结构，两种输入分别对应一种输出，有一侧控制端与一侧受控端，控制端流量为1时阻断受控端。</p><p><span id="source-block-msCpcnAU4hdiRv7T0efvi5"></span></p><h4 id="固固-流流-基本控制结构" tabindex="-1">固固\\流流-基本控制结构 <a class="header-anchor" href="#固固-流流-基本控制结构" aria-label="Permalink to &quot;固固\\流流-基本控制结构&quot;">​</a></h4><p>常用实现是优先汇流器→分类器，确保输入输出都是纯净两种，同时由优先汇流器的特性实现其中一端输入控制另一端输入的效果。最终效果类似优先汇流器，只是输出是多种。</p><p><span id="source-block-WAa6YT2JcwqSHP14sGqTCT"></span></p><h4 id="固液-基本控制结构" tabindex="-1">固液-基本控制结构 <a class="header-anchor" href="#固液-基本控制结构" aria-label="Permalink to &quot;固液-基本控制结构&quot;">​</a></h4><p>常用实现1：断电反应池可以接受固体与液体，通过这种方式可以实现同增同减（同一格），配合取反器即可实现基本控制结构，类似的，使用有液体+固体的配方的设备也可以直接达成同增同减。</p><p>常用实现2：类似断电</p><p><span id="source-block-BKd0bfBqMQYjGOon5TjRNh"></span></p><h3 id="均匀二进制分流器" tabindex="-1">均匀二进制分流器 <a class="header-anchor" href="#均匀二进制分流器" aria-label="Permalink to &quot;均匀二进制分流器&quot;">​</a></h3><p><span id="source-block-S59ZGmLv5iYu3bJX0M4vLU"></span></p><h4 id="bresenham算法" tabindex="-1">Bresenham算法 <a class="header-anchor" href="#bresenham算法" aria-label="Permalink to &quot;Bresenham算法&quot;">​</a></h4><p><span id="source-block-rJLuoyW0sbNOPnKggEQMI8"></span></p><h2 id="简单有理分流器的均匀性" tabindex="-1">简单有理分流器的均匀性 <a class="header-anchor" href="#简单有理分流器的均匀性" aria-label="Permalink to &quot;简单有理分流器的均匀性&quot;">​</a></h2><p><span id="source-block-saFuJ384PvuWkO0x5E0uld"></span></p><h2 id="均匀有理限流器" tabindex="-1">均匀有理限流器 <a class="header-anchor" href="#均匀有理限流器" aria-label="Permalink to &quot;均匀有理限流器&quot;">​</a></h2><p><span id="source-block-Uj5kS4ulgYdVqCL6baJ4Ku"></span></p><h3 id="闰年算法" tabindex="-1">闰年算法 <a class="header-anchor" href="#闰年算法" aria-label="Permalink to &quot;闰年算法&quot;">​</a></h3><p><span id="source-block-SmEDFRTyh8P5P9V7gXt3Kh"></span></p><h3 id="欧拉算法" tabindex="-1">欧拉算法 <a class="header-anchor" href="#欧拉算法" aria-label="Permalink to &quot;欧拉算法&quot;">​</a></h3><p><span id="source-block-xQRRd0h5FlKNP3iUeDlYjq"></span></p><h2 id="古典物流理论" tabindex="-1">古典物流理论 <a class="header-anchor" href="#古典物流理论" aria-label="Permalink to &quot;古典物流理论&quot;">​</a></h2></div>',1)])])}const b=e(t,[["render",n]]);export{u as __pageData,b as default};
